source='''def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(out), len(out[0])
    offsets = {1: (-1, 2), 2: (0, -4), 3: (3, 0), 6: (-6, 0)}
    paths = []
    seeds = []

    for r, row in enumerate(grid):
        for c, color in enumerate(row):
            if color not in offsets:
                continue
            dr, dc = offsets[color]
            er, ec = r + dr, c + dc
            if not (0 <= er < h and 0 <= ec < w):
                continue
            path = [(r, c)]
            if color == 1:
                step = 1 if dc > 0 else -1
                path.extend((r, cc) for cc in range(c + step, ec + step, step))
                path.append((er, ec))
            elif dr == 0:
                step = 1 if dc > 0 else -1
                path.extend((r, cc) for cc in range(c + step, ec + step, step))
            elif dc == 0:
                step = 1 if dr > 0 else -1
                path.extend((rr, c) for rr in range(r + step, er + step, step))
            paths.append((color, path))

    # Mark intermediate cells and endpoints for each ray.
    for color, path in paths:
        for r, c in path[1:-1]:
            if out[r][c] == 0:
                out[r][c] = 5
        r, c = path[-1]
        if grid[r][c] == 0:
            out[r][c] = color

    # Intersections of rays become color 4; extend each intersection down-left.
    occupancy = {}
    for color, path in paths:
        for pos in path:
            occupancy.setdefault(pos, set()).add(color)
    for (r, c), colors in occupancy.items():
        if len(colors) > 1:
            out[r][c] = 4
            seeds.append((r, c))
    for r, c in seeds:
        rr, cc = r, c
        while 0 <= rr < h and 0 <= cc < w:
            out[rr][cc] = 4
            rr += 1
            cc -= 1
    return out
'''
